248. /// Updates role assignments to match the recommended defaults for the target
249. /// mode, but only when a role's current model is also a default candidate
250. /// (i.e. it hasn't been customised). Returns the list of changes.
251. fn update_roles(
252.     root: &mut serde_yaml::Mapping,
253.     target: InitMode,
254. ) -> Result<Vec<(String, String, String)>, crate::CliError> {
255.     let mut changes = Vec::new();
256. 
257.     // Determine which models are available in this repo's config.
258.     let available = {
259.         let mut models: std::collections::BTreeMap<String, &'static str> =
260.             std::collections::BTreeMap::new();
261.         if let Some(m) = root
262.             .get(serde_yaml::Value::String("models".to_owned()))
263.             .and_then(serde_yaml::Value::as_mapping)
264.         {
265.             for key in m.keys() {
266.                 if let Some(id) = key.as_str() {
267.                     // Look up against the known catalogue.
268.                     if let Some(description) = available_model_ids().get(id).copied() {
269.                         models.insert(id.to_owned(), description);
270.                     }
271.                 }
272.             }
273.         }
274.         models
275.     };
276. 
277.     let recommended = recommended_role_bindings(target, &available);
278. 
279.     let roles_key = serde_yaml::Value::String("roles".to_owned());
280.     let Some(roles_val) = root.get_mut(&roles_key) else {
281.         return Ok(changes);
282.     };
283.     let Some(roles) = roles_val.as_mapping_mut() else {
284.         return Ok(changes);
285.     };
286. 
287.     for (role, new_model) in recommended.entries() {
288.         let role_key = serde_yaml::Value::String(role.to_owned());
289.         if let Some(current_val) = roles.get(&role_key) {
290.             let current = current_val.as_str().unwrap_or("").to_owned();
291.             if current != new_model {
292.                 roles.insert(role_key, serde_yaml::Value::String(new_model.to_owned()));
293.                 changes.push((role.to_owned(), current, new_model.to_owned()));
294.             }
295.         }
296.     }
297. 
298.     Ok(changes)
299. }
