     for (role, old, new) in &changes.role_changes {
         if styled {
             println!(
                 "  {:<18}  {role}: \x1b[33m{old}\x1b[0m → \x1b[32m{new}\x1b[0m",
                 "role"
             );
         } else {
             println!("  {:<18}  {role}: {old} → {new}", "role");
         }
     }
 }

 // ── Tests ─────────────────────────────────────────────────────────────────────

 #[cfg(test)]
 mod tests {
     use super::*;

     fn solo_yaml() -> serde_yaml::Value {
         serde_yaml::from_str(
             r#"
