         assert!(!changes.steps_removed.is_empty());
         let pipeline = yaml["pipeline"].as_sequence().unwrap();
         let ids: Vec<_> = pipeline
             .iter()
             .filter_map(|s| s.get("id")?.as_str())
             .collect();
         assert!(!ids.contains(&"bridge"));
