1. //! Claude Code session transcript parser for token telemetry (D14).
2. //!
3. //! Reads `~/.claude/projects/<repo-key>/<session>.jsonl` files and
4. //! aggregates token usage. Message deduplication is applied by `message.id`
5. //! since sidechain branching causes ~50% of lines to be duplicates.
6. 
7. use std::collections::HashSet;
8. use std::path::{Path, PathBuf};
9. 
10. use serde::Deserialize;
11. 
12. /// Aggregated token usage from one or more sessions.
13. #[derive(Debug, Default, Clone)]
14. pub(crate) struct TokenUsage {
15.     pub input_tokens: u64,
16.     pub output_tokens: u64,
17.     pub cache_read_input_tokens: u64,
18.     pub cache_creation_input_tokens: u64,
19.     /// Number of sessions contributing to this total.
20.     pub session_count: usize,
21.     /// Number of unique messages counted (after deduplication).
22.     pub message_count: usize,
23. }
24. 
25. impl TokenUsage {
26.     /// Sum of all token dimensions.
27.     pub fn total_tokens(&self) -> u64 {
28.         self.input_tokens
29.             .saturating_add(self.output_tokens)
30.             .saturating_add(self.cache_read_input_tokens)
31.             .saturating_add(self.cache_creation_input_tokens)
32.     }
33. 
34.     /// Tokens avoided at full input price due to cache hits.
35.     /// Anthropic cache reads cost ~10% of fresh input tokens, so 90% is saved.
36.     pub fn cache_savings_tokens(&self) -> u64 {
37.         (self.cache_read_input_tokens as f64 * 0.9) as u64
38.     }
39. }
40. 
41. /// Estimate USD cost for a session using claude-sonnet-4 pricing.
42. /// This is a rough estimate since session-level data doesn't have model breakdown.
43. pub(crate) fn estimate_session_cost_usd(usage: &TokenUsage) -> f64 {
44.     derrick_models::CostHint {
45.         in_per_mtok: 3.0,
46.         out_per_mtok: 15.0,
47.     }
48.     .estimate_usd(usage.input_tokens, usage.output_tokens)
49. }
50. 
