     let home = std::env::var("HOME").ok()?;
     let key = repo_root.to_str()?.replace('/', "-");
     let path = PathBuf::from(home)
         .join(".claude")
         .join("projects")
         .join(key);
     if path.is_dir() {
         Some(path)
     } else {
         None
     }
 }

